(7684832, 1257780, 76198, '<td valign="top">Overexposed. A subject in the foreground would have built interest. Neat location.</td>', 'Overexposed. A subject in the foreground would have built interest. Neat location.', '2021-01-18 22:13:37.000000', NULL, 1),
(7684833, 1257882, 76198, '<td valign="top">Funny, good approach to the theme, good use of extended editing. The compositing is obvious but meant to be, and it works. The bright sunlight on the subjects'' pants is a little distracting given that it''s supposed to be storming; also the blending between the sky and ground is in the uncanny valley - I''d have chosen to make it more abrupt rather than trying to blend it.</td>', 'Funny, good approach to the theme, good use of extended editing. The compositing is obvious but meant to be, and it works. The bright sunlight on the subjects'' pants is a little distracting given that it''s supposed to be storming; also the blending between the sky and ground is in the uncanny valley - I''d have chosen to make it more abrupt rather than trying to blend it.', '2021-01-18 22:16:00.000000', NULL, 1),
(7684834, 1257986, 76198, '<td valign="top">Very much to my taste.</td>', 'Very much to my taste.', '2021-01-18 22:16:24.000000', NULL, 1),
